// Space Debris Dodge
// Canvas with id="game" must exist in the HTML.
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = canvas.clientWidth || 800;
canvas.height = canvas.clientHeight || 600;

// Ship definition
const ship = {
  width: 30,
  height: 20,
  x: canvas.width / 2,
  y: canvas.height - 40,
  speed: 4,
  boostTimer: 0,
  draw() {
    ctx.fillStyle = 'white';
    ctx.beginPath();
    ctx.moveTo(this.x, this.y);
    ctx.lineTo(this.x - this.width / 2, this.y + this.height);
    ctx.lineTo(this.x + this.width / 2, this.y + this.height);
    ctx.closePath();
    ctx.fill();
  }
};

let debris = [];
let powerUps = [];
let score = 0;
let gameOver = false;
let spawnCounter = 0;
let powerCounter = 0;

// Input handling
const keys = {};
window.addEventListener('keydown', e => { keys[e.key] = true; });
window.addEventListener('keyup', e => { keys[e.key] = false; });

function spawnDebris() {
  const size = Math.random() * 20 + 10;
  debris.push({
    x: Math.random() * (canvas.width - size),
    y: -size,
    size,
    speed: 2 + Math.random() * 2 + score / 1000 // accelerate with score
  });
}

function spawnPowerUp() {
  const type = Math.random() < 0.5 ? 'boost' : 'clear';
  powerUps.push({
    x: Math.random() * (canvas.width - 20),
    y: -20,
    size: 20,
    speed: 2,
    type
  });
}

function update() {
  if (gameOver) return;

  // Move ship
  if (keys.ArrowLeft) ship.x -= ship.speed;
  if (keys.ArrowRight) ship.x += ship.speed;
  if (keys.ArrowUp) ship.y -= ship.speed;
  if (keys.ArrowDown) ship.y += ship.speed;
  // Keep inside canvas
  ship.x = Math.max(ship.width / 2, Math.min(canvas.width - ship.width / 2, ship.x));
  ship.y = Math.max(0, Math.min(canvas.height - ship.height, ship.y));

  // Boost timer decrement
  if (ship.boostTimer > 0) ship.boostTimer--;

  // Spawn debris gradually
  spawnCounter++;
  if (spawnCounter > 30) { // roughly every 0.5 sec at 60fps
    spawnDebris();
    spawnCounter = 0;
  }

  // Occasionally spawn power‑ups
  powerCounter++;
  if (powerCounter > 600) { // every ~10 sec
    spawnPowerUp();
    powerCounter = 0;
  }

  // Update debris positions
  debris.forEach(d => d.y += d.speed);
  // Remove off‑screen debris and increase score
  debris = debris.filter(d => {
    if (d.y - d.size > canvas.height) {
      score++;
      return false;
    }
    return true;
  });

  // Update power‑ups
  powerUps.forEach(p => p.y += p.speed);
  powerUps = powerUps.filter(p => p.y - p.size < canvas.height);

  // Collision detection
  const shipRect = {x: ship.x - ship.width / 2, y: ship.y, w: ship.width, h: ship.height};
  for (let i = 0; i < debris.length; i++) {
    const d = debris[i];
    if (rectIntersect(shipRect, {x: d.x, y: d.y, w: d.size, h: d.size})) {
      gameOver = true;
      break;
    }
  }
  // Power‑up collection
  for (let i = powerUps.length - 1; i >= 0; i--) {
    const p = powerUps[i];
    if (rectIntersect(shipRect, {x: p.x, y: p.y, w: p.size, h: p.size})) {
      if (p.type === 'boost') {
        ship.boostTimer = 300; // 5 seconds at 60fps
        ship.speed = 8;
      } else if (p.type === 'clear') {
        debris = [];
      }
      powerUps.splice(i, 1);
    }
  }
  // Reset speed after boost ends
  if (ship.boostTimer === 0) ship.speed = 4;
}

function draw() {
  ctx.fillStyle = '#000014';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  // stars background (simple static)
  ctx.fillStyle = 'rgba(255,255,255,0.3)';
  for (let i = 0; i < 50; i++) {
    const sx = Math.random() * canvas.width;
    const sy = Math.random() * canvas.height;
    ctx.fillRect(sx, sy, 1, 1);
  }

  ship.draw();

  // Draw debris
  ctx.fillStyle = 'gray';
  debris.forEach(d => {
    ctx.fillRect(d.x, d.y, d.size, d.size);
  });

  // Draw power‑ups
  powerUps.forEach(p => {
    ctx.fillStyle = p.type === 'boost' ? 'yellow' : 'cyan';
    ctx.fillRect(p.x, p.y, p.size, p.size);
  });

  // Score
  ctx.fillStyle = 'white';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: ' + score, 10, 20);

  if (gameOver) {
    ctx.fillStyle = 'red';
    ctx.font = '48px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  }
}

function rectIntersect(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

function loop() {
  update();
  draw();
  if (!gameOver) requestAnimationFrame(loop);
}

// Start the game
loop();
